<?php
namespace App\Http\Controllers;
use App\Models\{ImportBatch,ImportStagedRow,Person,SacramentalRecord};use App\Services\SacramentalRecordValidator;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ImportController extends Controller { public function store(Request $r,SacramentalRecordValidator $v){if(!$r->hasFile('file')||$r->file('file')->getSize()>5*1024*1024||!preg_match('/\.csv$/i',$r->file('file')->getClientOriginalName()))return response()->json(['error'=>'Upload a CSV no larger than 5MB'],422);$h=fopen($r->file('file')->getRealPath(),'r');$heads=fgetcsv($h);$rows=[];while(($x=fgetcsv($h))!==false){$raw=array_combine($heads,array_pad($x,count($heads),''));[$f,$e]=$v->validate($raw);$rows[]=['row'=>count($rows)+2,'data'=>$raw,'status'=>$e?'Invalid':'Valid','errors'=>$e];}fclose($h);$batch=ImportBatch::create(['filename'=>basename($r->file('file')->getClientOriginalName()),'uploaded_by'=>$r->user()->id,'total_rows'=>count($rows),'valid_rows'=>count(array_filter($rows,fn($x)=>$x['status']==='Valid'))]);foreach($rows as $row)ImportStagedRow::create(['batch_id'=>$batch->id,'row_number'=>$row['row'],'payload'=>$row['data'],'validation_errors'=>$row['errors']]);return response()->json(['data'=>['batch_id'=>$batch->id,'rows'=>$rows],'meta'=>['total'=>count($rows),'valid'=>$batch->valid_rows]],201);} public function commit(Request $r,ImportBatch $batch,SacramentalRecordValidator $v){if($batch->status!=='staged')return response()->json(['error'=>'Staged batch not found'],404);$n=DB::transaction(function()use($batch,$v,$r){$n=0;foreach($batch->rows as $row){[$f,$e]=$v->validate($row->payload);if($e)continue;$p=Person::firstOrCreate(['first_name'=>$f['first_name'],'last_name'=>$f['last_name'],'date_of_birth'=>$f['date_of_birth']?:null],$f);SacramentalRecord::create(['person_id'=>$p->id,'sacrament_type'=>$f['sacrament_type'],'event_date'=>$f['event_date'],'book_number'=>$f['book_number'],'page_number'=>$f['page_number'],'line_number'=>$f['line_number'],'minister_name'=>$f['minister_name']?:null,'sponsors'=>$f['sponsors']?:null,'margin_notes'=>$f['margin_notes']?:null,'source'=>'bulk_import','created_by'=>$r->user()->id]);$n++;}$batch->update(['committed_rows'=>$n,'status'=>'committed']);return $n;});return response()->json(['data'=>['committed_rows'=>$n]]);} public function destroy(ImportBatch $batch){if($batch->status==='staged')$batch->update(['status'=>'discarded']);return response()->json(['data'=>true]);} public function template(){return response()->download(storage_path('app/parish_bulk_import_template.csv'),'parish_bulk_import_template.csv',['Content-Type'=>'text/csv']);} }
